To reverse every **k nodes** of a linked list, you'll essentially follow these steps:

---

### 🔁 **Problem Statement**  
Given a singly linked list and an integer `k`, reverse every `k` nodes in the list. If the number of nodes is not a multiple of `k`, the remaining nodes at the end should remain as is.

---

### ✍️ **Example Input**
- Linked list: `1 -> 2 -> 3 -> 4 -> 5 -> 6 -> 7 -> 8`
- `k = 3`

---

### ✅ **Expected Output**
- Result: `3 -> 2 -> 1 -> 6 -> 5 -> 4 -> 7 -> 8`

---

### 🧠 **Approach (Iterative or Recursive)**
You can do it with a **recursive** or **iterative** approach. Here's the **iterative version** using C++:

---

### ✅ C++ Code

```cpp
#include <iostream>
using namespace std;

class Node {
public:
    int data;
    Node* next;

    Node(int value) {
        data = value;
        next = nullptr;
    }
};

// Function to reverse k nodes
Node* reverseKGroup(Node* head, int k) {
    if (!head || k == 1) return head;

    Node* dummy = new Node(0);
    dummy->next = head;

    Node* curr = dummy, *prev = dummy, *next = dummy;
    int count = 0;

    // Count total nodes
    while (curr->next) {
        curr = curr->next;
        count++;
    }

    while (count >= k) {
        curr = prev->next;
        next = curr->next;
        for (int i = 1; i < k; i++) {
            curr->next = next->next;
            next->next = prev->next;
            prev->next = next;
            next = curr->next;
        }
        prev = curr;
        count -= k;
    }

    return dummy->next;
}

// Utility to print list
void printList(Node* head) {
    while (head) {
        cout << head->data;
        if (head->next) cout << " -> ";
        head = head->next;
    }
    cout << endl;
}

// Utility to add node to end
void appendNode(Node*& head, int value) {
    Node* newNode = new Node(value);
    if (!head) {
        head = newNode;
        return;
    }
    Node* temp = head;
    while (temp->next) temp = temp->next;
    temp->next = newNode;
}

// 🔧 Driver code
int main() {
    Node* head = nullptr;
    for (int i = 1; i <= 8; ++i) {
        appendNode(head, i);
    }

    cout << "Original list:\n";
    printList(head);

    int k = 3;
    head = reverseKGroup(head, k);

    cout << "Modified list (every " << k << " nodes reversed):\n";
    printList(head);

    return 0;
}
```

---

### 📌 Notes:
- This code uses a dummy node to simplify head handling.
- The core logic is inside a for-loop that does in-place reversal for each group of `k`.
- If the remaining number of nodes is less than `k`, they are left unchanged.

