### ✅ Corrected C++ Code (All in `main()`):

```cpp
#include <iostream>
#include <string>
using namespace std;

int main() {
    string s;
    getline(cin, s);  // Read full input string

    string result = "";
    int i = 0;

    while (i < s.length()) {
        if (s[i] == '#' || s[i] == '$' || s[i] == '@' || s[i] == '*' || s[i] == '^') {
            i++; // skip special character

            // skip next alphabet character (not space or symbol)
            while (i < s.length() && !islower(s[i])) {
                result += s[i]; // keep non-alphabets like space
                i++;
            }

            if (i < s.length() && islower(s[i])) {
                i++; // skip the alphabet
            }

        } else {
            result += s[i];
            i++;
        }
    }

    cout << result << endl;
    return 0;
}
```

